-- Tanda UniX/SEO: copy de la landing de familia «robots» (hub de robots).
--
-- Cambia la meta description es/en para citar humanoides y cuadrúpedos UniX.
-- El contenido es exactamente el de src/data/familia-seo.ts (validado en landings-cms.test.ts).
-- Registra la versión nueva en el historial para poder volver atrás.
--
-- NO aplicar a producción sin OK explícito.

UPDATE public.landings
   SET contenido_es = $ime_landing${"name":"Robots de servicio e ingeniería robótica en Colombia","title":"Robots de servicio e ingeniería robótica en Colombia | I-ME","description":"Distribuidores de robots en Colombia: humanoides y cuadrúpedos UniX, recepción, telepresencia, limpieza autónoma y logística AMR con LiDAR SLAM.","intro":"I-ME distribuye robots de servicio en Colombia y hace la ingeniería de integración: recepción, telepresencia, logística interna, limpieza autónoma y educación, con navegación LiDAR SLAM sobre el plano real de la sede.","body":["El catálogo activo reúne ocho referencias: PadBot X3 y PadBot X2 (recepción), Cruzr (humanoide y Open API), PadBot P2 (telepresencia), PadBot W2 (gabinete PIN/QR), PadBot W3s (bandejas), robot C3 (limpieza 3-en-1) y PadBot T2 (educación y acompañamiento).","La comparación empieza por el edificio: recorridos, puertas, ascensores, superficies, puntos de carga y el responsable de operación. La integración multiplanta usa puntos de espera y abordaje de ascensor (módulo IoT E-Box o API Cloud) y puntos de control de acceso.","Otras arquitecturas —limpieza industrial pesada, desinfección UV-C o logística cerrada— se estudian como ingeniería bajo proyecto y no se publican como SKUs nuevos. La garantía es la del fabricante, con soporte electromecánico local de I-ME."],"faq":[{"q":"¿I-ME es un distribuidor de robots de servicio en Colombia?","a":"Sí. Publica ocho robots de recepción, telepresencia, logística, limpieza y educación, y acompaña la ingeniería de integración en la sede. El alcance se confirma en la propuesta."},{"q":"¿Puede integrarse con ascensores o torniquetes?","a":"En los modelos cuyo manual lo describe, sí: puntos de espera y abordaje de ascensor con módulo IoT E-Box o API Cloud, y control de acceso para puertas y torniquetes. Se valida en el plano de la sede."},{"q":"¿La navegación exige obra civil o cinta magnética?","a":"Los manuales de esta línea describen mapas SLAM con LiDAR, sin reflectores ni balizas magnéticas. Sensores de ultrasonido, anticaída y parachoques cubren vidrio, escaleras y contacto."}]}$ime_landing$::jsonb,
       contenido_en = $ime_landing${"name":"Service robots and robotics engineering in Colombia","title":"Service robots and robotics engineering in Colombia | I-ME","description":"Robot distributors in Colombia: UniX humanoids and quadrupeds, reception, telepresence, autonomous cleaning and AMR logistics with LiDAR SLAM.","intro":"I-ME distributes service robots in Colombia and engineers the integration: reception, telepresence, internal logistics, autonomous cleaning and education, with LiDAR SLAM navigation on the real floor plan.","body":["The active catalog has eight references: PadBot X3 and PadBot X2 (reception), Cruzr (humanoid and Open API), PadBot P2 (telepresence), PadBot W2 (PIN/QR cabinet), PadBot W3s (trays), the C3 robot (3-in-1 cleaning) and PadBot T2 (education and companionship).","Comparison starts with the building: routes, doors, elevators, floors, charge points and the operating owner. Multi-floor integration uses elevator waiting and boarding points (E-Box IoT module or cloud API) and access-control points.","Other architectures — heavy industrial cleaning, UV-C disinfection or closed logistics — are studied as project engineering and are not published as new SKUs. Warranty is the manufacturer’s, with local electromechanical support from I-ME."],"faq":[{"q":"Is I-ME a service-robot distributor in Colombia?","a":"Yes. It publishes eight reception, telepresence, logistics, cleaning and education robots, and supports on-site integration engineering. Scope is confirmed in the proposal."},{"q":"Can it integrate with elevators or turnstiles?","a":"On models whose manual describes it, yes: elevator waiting and boarding points via the E-Box IoT module or a cloud API, and access control for doors and turnstiles. It is validated on the site drawing."},{"q":"Does navigation require civil works or magnetic tape?","a":"Manuals for this line describe SLAM maps with LiDAR, without reflectors or magnetic beacons. Ultrasound, cliff sensors and bumpers cover glass, stairs and contact."}]}$ime_landing$::jsonb,
       version = version + 1,
       publicado_at = NOW()
 WHERE tipo = 'familia' AND clave = 'robots';

INSERT INTO public.landings_historial (landing_id, version, contenido_es, contenido_en)
SELECT id, version, contenido_es, contenido_en
FROM public.landings
WHERE tipo = 'familia' AND clave = 'robots'
ON CONFLICT (landing_id, version) DO NOTHING;
